-- SEED Inventaire DARE1 — généré depuis les 4 fichiers Station Inventory
-- Idempotent : purge les documents (cascade → items) avant réinsertion.
-- À exécuter APRÈS la migration 20260712_v10_inventory_module.sql
BEGIN;
DELETE FROM public.inventaire_documents WHERE id IN ('DARE1-DJIBOUTI-I20','DARE1-MOMBASA-I20','DARE1-BOSASO-I10','DARE1-MOGADISHU-I10');



UPDATE public.inventaire_documents d SET item_count = (SELECT COUNT(*) FROM public.inventaire_items i WHERE i.document_id = d.id);
COMMIT;